export type OpsVersionRow = {
  releaseTrack: string;
  date: string;
  version: string;
  name: string;
  meaning: string;
  why: string;
  landing: string;
  status: 'PLANNED' | 'UNVERIFIED' | 'COMPLETED_STEP1' | 'BRIDGE_ONLY' | 'PASS' | 'FAIL';
  availability: string;
  runRef: string;
  evidenceRefs: string[];
};

export type WorkflowRow = {
  createdUpdated: string;
  idPath: string;
  workflow: string;
  trigger: string;
  purpose: string;
  objective: string;
  useCase: string;
  triggerWhen: string;
  source: string;
  mode: string;
};

export type StepBlock = {
  step: 1 | 2 | 3 | 4;
  title: string;
  status: 'PENDING' | 'PASS' | 'FAIL';
  lines: string[];
  artifacts: string[];
};

export type VersionDetail = {
  releaseTrack: string;
  versionKey: string;
  date: string;
  version: string;
  name: string;
  meaning: string;
  why: string;
  purpose: string;
  targets: { pass: string; fail: string };
  workflowName: string;
  workflowUseCase: string;
  status: string;
  verificationStatus: string;
  dataMode: string;
  updatedAt: string;
  digest: string;
  steps: StepBlock[];
  inputs: Array<{ path: string; digest: string; summary: string; note: string }>;
  outputs: Array<{ path: string; digest: string; summary: string; note: string }>;
  references: Array<{ title: string; path: string; desc: string }>;
  contractSummary: {
    sourceOfTruth: string;
    verdict: string;
    reasonCode: string;
    dataSource: string;
    dataDate: string;
  };
};

type HistoricalVersionSeed = {
  date: string;
  version: string;
  name: string;
  status: 'PLANNED' | 'PASS';
  evidencePath: string;
  extraEvidencePaths?: string[];
  meaning?: string;
  why?: string;
  landing?: string;
};

